import React from 'react';
import { Link } from 'react-router-dom';

const Sidebar = ({ role }) => {
    return (
        <div style={{ width: '200px', minHeight: '100vh', background: '#373839', borderRight: '1px solid #ced4da', padding: '20px 0' }}>
            <div style={{ fontSize: '20px', fontWeight: '700', color: '#343a40', padding: '0 20px 20px', borderBottom: '1px solid #ced4da', marginBottom: '10px' }}>EMS</div>
            <nav>
                {role === 'ADMIN' && (
                    <>
                        <Link to="/" style={{ display: 'block', padding: '10px 20px', color: '#495057', textDecoration: 'none' }}>Dashboard</Link>
                        <Link to="/add-employee/_add" style={{ display: 'block', padding: '10px 20px', color: '#495057', textDecoration: 'none' }}>Add Employee</Link>
                    </>
                )}
                {role === 'EMPLOYEE' && (
                    <Link to="/dashboard" style={{ display: 'block', padding: '10px 20px', color: '#495057', textDecoration: 'none' }}>My Profile</Link>
                )}
            </nav>
        </div>
    );
};

export default Sidebar;
